static int atc_pause ( struct dma_chan * chan ) { struct at_dma_chan * atchan = to_at_dma_chan ( chan ) ; struct at_dma * atdma = to_at_dma ( chan -> device ) ; int chan_id = atchan -> chan_common . chan_id ; unsigned long flags ; LIST_HEAD ( list ) ; dev_vdbg ( chan2dev ( chan ) , "%s\n" , __func__ ) ; spin_lock_irqsave ( & atchan -> lock , flags ) ; dma_writel ( atdma , CHER , AT_DMA_SUSP ( chan_id ) ) ; set_bit ( ATC_IS_PAUSED , & atchan -> status ) ; return 0 ; } 